# Apply only a fresh audit generated by audit_native_cache.py. Preview is default.
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [string]$AuditDirectory,
    [switch]$Apply
)

$ErrorActionPreference = 'Stop'
$repoPath = [System.IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot))
$auditRoot = [System.IO.Path]::GetFullPath((Join-Path $repoPath $AuditDirectory))
$logsPrefix = (Join-Path $repoPath 'logs') + [System.IO.Path]::DirectorySeparatorChar
if (-not $auditRoot.StartsWith($logsPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
    throw 'The audit must be inside this project logs directory.'
}
$snapshot = Get-Content -LiteralPath (Join-Path $auditRoot 'audit-fingerprints.json') -Raw | ConvertFrom-Json
foreach ($entry in @($snapshot.Files)) {
    if ((Get-FileHash -LiteralPath $entry.Path -Algorithm SHA256).Hash -ne $entry.Hash) {
        throw "The audited inputs changed; regenerate the audit: $($entry.Path)"
    }
}
$plan = @(Import-Csv -LiteralPath (Join-Path $auditRoot 'deletion-plan.csv'))
$keep = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
Import-Csv -LiteralPath (Join-Path $auditRoot 'keep_names.csv') | ForEach-Object { [void]$keep.Add($_.name) }
$references = @(Import-Csv -LiteralPath (Join-Path $auditRoot 'referenced_files.csv'))
$objectRoot = Join-Path $repoPath '_targets/objects'
$partitionRoot = Join-Path $repoPath '_targets/user/partitions'
foreach ($item in $plan) {
    $path = [System.IO.Path]::GetFullPath($item.Path)
    $allowed = switch ($item.Kind) {
        'object' { $objectRoot }
        'generated' { $partitionRoot }
        default { throw 'Unknown cleanup category.' }
    }
    $prefix = [System.IO.Path]::GetFullPath($allowed) + [System.IO.Path]::DirectorySeparatorChar
    if (-not $path.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "The deletion path is outside its allowed cache directory: $path"
    }
    if ($item.Kind -eq 'object' -and $keep.Contains([System.IO.Path]::GetFileName($path))) {
        throw "The plan includes a retained object: $path"
    }
    foreach ($reference in $references) {
        $refPath = [System.IO.Path]::GetFullPath($reference.local)
        if ($path.Equals($refPath, [System.StringComparison]::OrdinalIgnoreCase) -or
            $path.StartsWith($refPath + [System.IO.Path]::DirectorySeparatorChar, [System.StringComparison]::OrdinalIgnoreCase)) {
            throw "The plan includes a referenced file: $path"
        }
    }
    $current = Get-Item -LiteralPath $path
    if ($current.PSIsContainer -or $current.Length -ne [long]$item.Bytes) {
        throw "An audited file changed: $path"
    }
}
$bytes = ($plan | Measure-Object -Property Bytes -Sum).Sum
Write-Output ("Verified unused files: {0}; logical size: {1:N3} GiB" -f $plan.Count, ($bytes / 1GB))
if (-not $Apply) {
    Write-Output 'Preview only. No files or metadata were changed.'
    return
}
$freeBefore = (Get-PSDrive -Name D).Free
$removed = 0
foreach ($item in $plan) {
    Remove-Item -LiteralPath $item.Path -Force
    $removed++
    if ($removed % 2000 -eq 0) { Write-Output "Removed $removed / $($plan.Count) audited unused files" }
}
# Keep empty directories; metadata pruning is a separate native targets operation.
[pscustomobject]@{
    Removed = $removed
    LogicalGiB = [math]::Round($bytes / 1GB, 3)
    FreeBeforeGiB = [math]::Round($freeBefore / 1GB, 3)
    FreeAfterGiB = [math]::Round((Get-PSDrive -Name D).Free / 1GB, 3)
    Finished = (Get-Date).ToString('o')
} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $auditRoot 'cleanup-completed.json') -Encoding utf8
Write-Output 'Completed audited file cleanup. Current native objects and input data were retained.'
